from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
left_drive = Motor(Port.F, Direction.COUNTERCLOCKWISE)
right_drive = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(left_drive, right_drive, 56, 114)


# The main program starts here.
print('Starting Gyro Test')
drive_base.use_gyro(True)
drive_base.reset(0, 0)
drive_base.settings(turn_rate=50)
print(drive_base.angle())
while not drive_base.angle() > 89:
    drive_base.turn(1, then=Stop.NONE)
